class Solution {
public:
    int countSpecialSubsequences(vector<int>& nums) {
        const int MOD = 1e9 + 7;
        long long dp0 = 0, dp1 = 0, dp2 = 0;
        for (int x : nums) {
            if (x == 0) {
                dp0 = (2 * dp0 + 1) % MOD;
            } else if (x == 1) {
                dp1 = (2 * dp1 + dp0) % MOD;
            } else if (x == 2) {
                dp2 = (2 * dp2 + dp1) % MOD;
            }
        }
        return dp2;
    }
};

class Solution {
    public int countSpecialSubsequences(int[] nums) {
        final int MOD = 1_000_000_007;
        long dp0 = 0, dp1 = 0, dp2 = 0;
        for (int x : nums) {
            if (x == 0) {
                dp0 = (2 * dp0 + 1) % MOD;
            } else if (x == 1) {
                dp1 = (2 * dp1 + dp0) % MOD;
            } else if (x == 2) {
                dp2 = (2 * dp2 + dp1) % MOD;
            }
        }
        return (int) dp2;
    }
}

var countSpecialSubsequences = function(nums) {
  const MOD = 1000000007;
  let dp0 = 0, dp1 = 0, dp2 = 0;
  for (const x of nums) {
    if (x === 0) {
      dp0 = (2 * dp0 + 1) % MOD;
    } else if (x === 1) {
      dp1 = (2 * dp1 + dp0) % MOD;
    } else if (x === 2) {
      dp2 = (2 * dp2 + dp1) % MOD;
    }
  }
  return dp2;
};
